/**
 * Writes src/names.generated.ts, src/registry.generated.ts and src/sprite.generated.svg: the closed set of lucide-react icons XOS draws by name, imported
 * one by one so bundlers keep only these icons (RRR-70). Sources are every registry/<owner>.txt
 * (one PascalCase lucide-react name per line, `#` starts a comment) plus every glyph in src/map.json.
 * Each owner keeps its own list, so parallel branches never conflict in a shared file (ADR 0021);
 * on a conflict in the generated file, rerun this script.
 *
 * Usage: node scripts/generate-registry.mjs [--check]
 * With --check, writes nothing and exits 1 when the generated file is out of date or a name does
 * not exist in the pinned lucide-react.
 */
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import * as prettier from "prettier";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const lucide = createRequire(import.meta.url)("lucide-react");

const owners = new Map();
function add(name, owner) {
  if (!owners.has(name)) owners.set(name, new Set());
  owners.get(name).add(owner);
}

const map = JSON.parse(readFileSync(join(root, "src/map.json"), "utf8"));
for (const table of [map.departments, map.phases, map.recordKinds]) {
  for (const name of Object.values(table)) add(name, "map.json");
}

const registryDir = join(root, "registry");
for (const file of readdirSync(registryDir)
  .filter((f) => f.endsWith(".txt"))
  .sort()) {
  const lines = readFileSync(join(registryDir, file), "utf8").split(/\r?\n/);
  for (const raw of lines) {
    const name = raw.replace(/#.*/, "").trim();
    if (name) add(name, file);
  }
}

const problems = [];
for (const [name, from] of owners) {
  const where = [...from].join(", ");
  if (!/^[A-Z][A-Za-z0-9]*$/.test(name)) {
    problems.push(`${name} (${where}) is not a PascalCase lucide-react name`);
  } else if (name.startsWith("Lucide") || name.endsWith("Icon") || name === "Icon") {
    problems.push(`${name} (${where}) is an alias form; list the base name`);
  } else if (typeof lucide[name] !== "object" && typeof lucide[name] !== "function") {
    problems.push(`${name} (${where}) does not exist in lucide-react ${map.library.version}`);
  }
}
if (problems.length > 0) {
  console.error(`Icon registry has ${problems.length} invalid names:\n  ${problems.join("\n  ")}`);
  process.exit(1);
}

const names = [...owners.keys()].sort();
const header = `/* Generated by scripts/generate-registry.mjs from registry/*.txt and src/map.json. Do not edit; run \`pnpm --filter @xos/icons generate:registry\`. */`;

const namesSource = `${header}

/** Every icon name XOS draws by name, sorted. Imports nothing, so a bundle that only checks names stays small. */
export const registeredIconNames = ${JSON.stringify(names)} as const;

export type RegisteredIconName = (typeof registeredIconNames)[number];
`;

const registrySource = `${header}
import type { LucideIcon } from "lucide-react";
import { ${names.map((n) => `${n} as Lucide${n}`).join(", ")} } from "lucide-react";
import { registeredIconNames, type RegisteredIconName } from "./names.generated.ts";

export { registeredIconNames, type RegisteredIconName };

/** The lucide-react component for each registered name. Only these icons reach a bundle. */
export const iconRegistry: Readonly<Record<RegisteredIconName, LucideIcon>> = /* @__PURE__ */ Object.freeze({ ${names
  .map((n) => `${n}: Lucide${n}`)
  .join(", ")} });
`;

/** XML attribute text: lucide's path data never needs more than these escapes. */
function attr(value) {
  return String(value).replaceAll("&", "&amp;").replaceAll('"', "&quot;").replaceAll("<", "&lt;");
}

/**
 * The web icon sprite (ADR 0027): one <symbol> per registered icon, drawn from the same pinned
 * lucide-react data as the components. Symbols carry only geometry, so the referencing <svg> sets
 * stroke, size and color for each use.
 */
function symbol(name) {
  const data = lucide[name].render({}, null).props.icon;
  const size = data.size ?? 24;
  const children = data.node
    .map(([tag, attrs]) => {
      const text = Object.entries(attrs)
        .filter(([k]) => k !== "key")
        .map(([k, v]) => ` ${k}="${attr(v)}"`)
        .join("");
      return `<${tag}${text}/>`;
    })
    .join("");
  return `<symbol id="${name}" viewBox="0 0 ${size} ${size}">${children}</symbol>`;
}
// Width and height let Next.js read the file as a static image import; uses ignore them.
const sprite = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24">\n${names.map(symbol).join("\n")}\n</svg>\n`;

const outputs = [];
for (const [file, source] of [
  ["src/names.generated.ts", namesSource],
  ["src/registry.generated.ts", registrySource],
]) {
  const path = join(root, file);
  const config = (await prettier.resolveConfig(path)) ?? {};
  outputs.push([file, await prettier.format(source, { ...config, filepath: path })]);
}
outputs.push(["src/sprite.generated.svg", sprite]);

if (process.argv.includes("--check")) {
  const stale = outputs.filter(([file, output]) => {
    try {
      return readFileSync(join(root, file), "utf8") !== output;
    } catch {
      return true;
    }
  });
  if (stale.length > 0) {
    console.error(
      `${stale.map(([file]) => file).join(", ")} out of date. Run pnpm --filter @xos/icons generate:registry.`,
    );
    process.exit(1);
  }
} else {
  for (const [file, output] of outputs) writeFileSync(join(root, file), output);
  console.log(`Wrote ${names.length} icons to the names, registry and sprite files in src/.`);
}
